// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    await page.waitForLoadState('networkidle');

    const qtySelect = page.locator('#quantity');
    await qtySelect.waitFor({ state: 'visible', timeout: 10000 });
    await expect(page.locator('label[for="quantity"]')).toContainText("Qty:");
    await expect(qtySelect).toHaveValue("1");
    await expect(qtySelect.locator('option')).toHaveCount(10);

    // Styling regression: product.html renamed the wrapper class to
    // "product-quantity-selector" and added class "qty-select" on the <select>,
    // but styles.css still only defines rules for the old ".product-quantity-dropdown"
    // (styles.css:463-478). With no rule matching either new class the select loses
    // its intended sizing (width:100% of a 100px wrapper, height:45px, padding:10px 16px)
    // and collapses to roughly 18x26px, which is too small to operate.
    const qtyBox = await qtySelect.boundingBox();
    expect(qtyBox).not.toBeNull();
    expect(qtyBox!.width).toBeGreaterThanOrEqual(60);
    expect(qtyBox!.height).toBeGreaterThanOrEqual(40);
});
